<?php
// Run only in disposable checkout, with unshare -n. DB contains synthetic data only.
$base=dirname(__DIR__,3).'/linkstack';
if (!str_starts_with(realpath($base),'/tmp/linkfree-audit/')) throw new RuntimeException('Isolated path required');
chdir($base);require 'vendor/autoload.php';$app=require 'bootstrap/app.php';
$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();
use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Auth;use Illuminate\Http\Request;use App\Models\User;use App\Services\ReferralService as Ref;use App\Http\Controllers\VerificationController as VC;use App\Http\Controllers\AbuseReportController as RC;
if(config('database.connections.sqlite.database')!==$base.'/database/audit.sqlite')throw new RuntimeException('Unsafe database');
config(['session.driver'=>'array','cache.default'=>'array','mail.default'=>'array','mail.mailers.array'=>['transport'=>'array'],'linkstack.disable_random_user_ids'=>'true']);
$session=app('session')->driver();$session->start();
$results=[];
function check($id,$name,$fn){global $results;try{$fn();$results[]=['id'=>$id,'assertion'=>$name,'pass'=>true];echo "PASS $id $name\n";}catch(Throwable $e){$results[]=['id'=>$id,'assertion'=>$name,'pass'=>false,'error'=>$e->getMessage()];echo "FAIL $id $name: ".$e->getMessage()."\n";}}
function ok($v,$m='assertion failed'){if(!$v)throw new RuntimeException($m);}
function req($data=[],$url='/audit',$method='POST'){global $session;$r=Request::create('https://audit.example.test'.$url,$method,$data);$r->setLaravelSession($session);app()->instance('request',$r);return $r;}
function user($name,$role='user'){ $u=User::create(['name'=>$name,'email'=>$name.'@example.test','littlelink_name'=>$name,'password'=>bcrypt('Synthetic-password-123'),'email_verified_at'=>now()]);$u->role=$role;$u->save();return $u;}

$u=User::where('email','auditfree@example.test')->firstOrFail();$a=User::where('email','auditadmin@example.test')->firstOrFail();
check('TC-05-D','member 15 and admin 20 item pagination with exact totals',function()use($u,$a){for($i=0;$i<22;$i++){$n=user('page'.$i);DB::table('referrals')->insert(['referrer_user_id'=>$u->id,'invited_user_id'=>$n->id,'referral_code'=>Ref::ensureCode($u),'created_at'=>now(),'updated_at'=>now()]);}Auth::login($u);$c=new App\Http\Controllers\ReferralController;$d=$c->index()->getData();ok($d['history']->count()===15 && $d['history']->total()===23);Auth::login($a);$d=$c->adminIndex(req(['referrer_id'=>$u->id]))->getData();ok($d['history']->count()===20 && $d['history']->total()===23);});
check('TC-07-D','report pagination 20 items and status filtered totals',function()use($a){Auth::login($a);$c=new RC;for($i=0;$i<22;$i++)$c->store(req(['url'=>'https://example.test','report-type'=>'fraud_scams']));$d=$c->index(req(['status'=>'new'],'/admin/reports','GET'))->getData();ok($d['reports']->count()===20);ok($d['reports']->total()===DB::table('abuse_reports')->where('status','new')->count());ok($d['totalCount']===DB::table('abuse_reports')->count());});
check('TC-07-F','deleting reporter and reviewer preserves events',function(){ $target=user('delete2target');$reporter=user('delete2reporter');$reviewer=user('delete2reviewer','admin');Auth::login($reporter);$c=new RC;$c->store(req(['user_id'=>$target->id,'url'=>'https://example.test','report-type'=>'fraud_scams']));$id=DB::table('abuse_reports')->max('id');Auth::login($reviewer);$c->update(req(['status'=>'resolved','note'=>'synthetic']),$id);foreach([$target,$reporter,$reviewer] as $x)$x->delete();$r=DB::table('abuse_reports')->find($id);ok($r->reported_user_id===null && $r->reporter_user_id===null && $r->reviewed_by===null);ok(DB::table('abuse_report_events')->where('abuse_report_id',$id)->count()===2);ok(DB::table('abuse_report_events')->where('abuse_report_id',$id)->whereNotNull('actor_user_id')->count()===0);});
check('TC-08-A','persisted decorative blocks do not consume quota',function()use($u){$before=App\Services\UserLinkLimit::count($u->id);foreach(['heading','spacer','text'] as $type){DB::table('links')->insert(['user_id'=>$u->id,'button_id'=>1,'type'=>$type,'title'=>'Synthetic decoration']);}ok(App\Services\UserLinkLimit::count($u->id)===$before);});
check('TC-03-B','theme selection and permissions persist after cache flush',function()use($u){Auth::login($u);(new App\Http\Controllers\UserController)->editTheme(req(['theme'=>'default']));ok($u->fresh()->theme==='default');App\Services\ThemeOptions::savePermissions(['font_family'=>'1']);Illuminate\Support\Facades\Cache::flush();ok(App\Services\ThemeOptions::permissions()['font_family']===true);});
check('TC-10-B','synthetic 500 renders without private exception marker',function(){ $res=app(Illuminate\Contracts\Debug\ExceptionHandler::class)->render(req([], '/audit-failure','GET'),new RuntimeException('SYNTHETIC_PRIVATE_MARKER'));ok($res->getStatusCode()===500);ok(!str_contains($res->getContent(),'SYNTHETIC_PRIVATE_MARKER'));ok(!str_contains($res->getContent(),'Stack trace'));});
file_put_contents(dirname(__DIR__).'/evidencias/extended-coverage.json',json_encode($results,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE));
